  var svg = document.getElementById("aon6-svg");
  var feedback = document.getElementById("aon6-feedback");
  var cpFeedback = document.getElementById("aon6-cpfeedback");

  function el(id) { return document.getElementById(id); }

  function updateFloat(id) {
    var esVal = parseFloat(el("aon6-ES-" + id).value);
    var lsVal = parseFloat(el("aon6-LS-" + id).value);
    var span = el("aon6-FLT-" + id);
    if (!isNaN(esVal) && !isNaN(lsVal)) {
      span.textContent = lsVal - esVal;
    } else {
      span.innerHTML = "&nbsp;";
    }
  }

  function layoutArrows() {
    var rect = diagram.getBoundingClientRect();
    var w = diagram.scrollWidth, h = diagram.scrollHeight;
    svg.setAttribute("width", w);
    svg.setAttribute("height", h);
    svg.setAttribute("viewBox", "0 0 " + w + " " + h);
    while (svg.children.length > 1) { svg.removeChild(svg.lastChild); }
    edges.forEach(function (e) {
      var a = el("aon6-node-" + e[0]).getBoundingClientRect();
      var b = el("aon6-node-" + e[1]).getBoundingClientRect();
      var x1 = a.right - rect.left, y1 = a.top - rect.top + a.height / 2;
      var x2 = b.left - rect.left, y2 = b.top - rect.top + b.height / 2;
      var line = document.createElementNS("http://www.w3.org/2000/svg", "line");
      line.setAttribute("x1", x1); line.setAttribute("y1", y1);
      line.setAttribute("x2", x2 - 6); line.setAttribute("y2", y2);
      line.setAttribute("stroke", "#2E86C1");
      line.setAttribute("stroke-width", "2");
      line.setAttribute("marker-end", "url(#aon6-arrowhead)");
      svg.appendChild(line);
    });
  }

  nodes.forEach(function (n) {
    ["ES", "LS"].forEach(function (f) {
      el("aon6-" + f + "-" + n.id).addEventListener("input", function () { updateFloat(n.id); });
    });
    el("aon6-node-" + n.id).addEventListener("click", function (ev) {
      if (ev.target.tagName.toLowerCase() === "input") return;
      this.classList.toggle("cp-selected");
    });
  });

  el("aon6-btn-check").addEventListener("click", function () {
    var total = 0, correct = 0;
    var answers = { ES: ES, EF: EF, LS: LS, LF: LF };
    nodes.forEach(function (n) {
      ["ES", "EF", "LS", "LF"].forEach(function (f) {
        total++;
        var input = el("aon6-" + f + "-" + n.id);
        var cell = input.parentElement;
        cell.classList.remove("correct", "incorrect");
        var val = parseFloat(input.value);
        if (!isNaN(val) && val === answers[f][n.id]) {
          cell.classList.add("correct");
          correct++;
        } else {
          cell.classList.add("incorrect");
        }
      });
      updateFloat(n.id);
    });
    feedback.textContent = correct + " of " + total + " cells correct." +
      (correct === total ? " Every number checks out -- on to the critical path." : " Fix the red cells and check again.");
  });

  el("aon6-btn-cp").addEventListener("click", function () {
    nodes.forEach(function (n) {
      var node = el("aon6-node-" + n.id);
      var selected = node.classList.contains("cp-selected");
      node.classList.remove("cp-selected", "cp-correct", "cp-missed", "cp-wrong");
      if (selected && CRIT[n.id]) node.classList.add("cp-correct");
      else if (!selected && CRIT[n.id]) node.classList.add("cp-missed");
      else if (selected && !CRIT[n.id]) node.classList.add("cp-wrong");
    });
    var chain = nodes.filter(function (n) { return CRIT[n.id]; }).map(function (n) { return n.id; }).join("-");
    cpFeedback.textContent = "Critical path: " + chain + " (" + proj + " days). Green = correctly on the critical path, red outline = missed or wrongly selected.";
  });

  el("aon6-btn-reset").addEventListener("click", function () {
    nodes.forEach(function (n) {
      ["ES", "EF", "LS", "LF"].forEach(function (f) {
        var input = el("aon6-" + f + "-" + n.id);
        input.value = "";
        input.parentElement.classList.remove("correct", "incorrect");
      });
      el("aon6-FLT-" + n.id).innerHTML = "&nbsp;";
      el("aon6-node-" + n.id).classList.remove("cp-selected", "cp-correct", "cp-missed", "cp-wrong");
    });
    feedback.textContent = "";
    cpFeedback.textContent = "";
  });

  layoutArrows();
  window.addEventListener("resize", layoutArrows);
  window.addEventListener("load", layoutArrows);
  setTimeout(layoutArrows, 200);
})();
</script>

